/* Cálculo de uniones territoriales: cada superficie elemental se cuenta una vez.
   Los datos se derivan de las geometrías originales; las claves de relación son estables. */
window.RENPA_CALCULAR_ESTADISTICAS=function(ids,datos,admitida,filtro){
 const base=window.RENPA_ATOMOS;
 if(!base||base.version!==1)throw new Error('Falta la base de superficies territoriales');
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
 let total=0,protegida=0;const figuras=Object.create(null);
 for(const id of ids){
  const registro=base.municipios[id],m=datos[id];
  if(!registro||!m)throw new Error('Faltan superficies para '+id);
  const [area,claves,zonas]=registro;
  const relaciones=new Map(m.espacios.map(e=>[[e.figura,e.espacio,e.tipo].map(norm).join('||'),e]));
  if(relaciones.size!==new Set(claves).size||claves.some(k=>!relaciones.has(k)))throw new Error('Las relaciones y la base territorial no corresponden a la misma cartografía');
  total+=area;
  const activas=claves.map(k=>{const e=relaciones.get(k);return admitida(id,e)&&(!filtro||norm(e.tipo)===norm(filtro))?e.tipo:null;});
  for(const [indices,ha] of zonas){
   const tipos=new Set(indices.map(i=>activas[i]).filter(Boolean));
   if(tipos.size===0)continue;
   protegida+=ha;
   for(const tipo of tipos)figuras[tipo]=(figuras[tipo]||0)+ha;
  }
 }
 return {total,protegida,porcentaje:total?100*protegida/total:0,figuras};
};
